/* Buck (chopper) com carga RL, com o controle como num DSP: o mesmo do controle.py, em C (o que vai para o alvo).
   O PWM é o ePWM (o pwm.c da biblioteca), e os registradores dele estão nos parâmetros do painel:
     f_clk = 100 MHz, TBPRD = 5000, CTRMODE = 2 (sobe-desce) → PWM de 2·TBPRD/f_clk = 100 µs (10 kHz);
     INTSEL = 1: a interrupção em CTR = 0 → o Ts = 100 µs sai daí (o campo Ts fica só leitura);
     SHDWAMODE = 0: o CMPA escrito agora só vale no próximo CTR = 0 (o registrador sombra);
     DB: o tempo morto, em contagens.
   A cada interrupção: lê i_L (em CTR = 0, a média do período), calcula d, escreve CMPA = d·TBPRD. O pwm_pulsos devolve o
   pulso do intervalo (contado a f_clk) para a atuação g. No alvo, o pwm_pulsos vira a escrita do CMPA no ePWM.
   O atraso da malha fica em ~1,5·Ts: no cruzamento de 500 Hz, ~27° de fase (veja o controle.py e o GUIA_CONTROLE 4.4). */
#include "maisim_controle.h"
#include "pwm.h"

typedef struct {
    PwmRegistradores pwm;
    maisim_real integral;
} Estado;

size_t maisim_tamanho_estado(void) { return sizeof(Estado); }

void maisim_iniciar(const maisim_real p[MAISIM_N_P], void *estado) {
    Estado *e = (Estado *)estado;
    pwm_iniciar_registradores(&e->pwm, p);   /* o ePWM: lê f_clk, TBPRD, CTRMODE, SHDWAMODE, INTSEL e DB */
    e->integral = 0.0;
}

void maisim_passo(maisim_real t, const maisim_real m[MAISIM_N_M], const maisim_real p[MAISIM_N_P], void *estado,
                  maisim_real u[MAISIM_N_U]) {
    Estado *e = (Estado *)estado;
    maisim_real erro = p[P_i_ref] - m[M_i_L];                 /* a amostra em CTR = 0: a média do período */
    maisim_real d_ff = p[P_k_ff] * p[P_R] * p[P_i_ref] / p[P_Vdc];
    maisim_real integral = e->integral + erro * p[P_Ts];
    maisim_real d = d_ff + (p[P_Kp] * erro + p[P_Ki] * integral) / p[P_Vdc];
    maisim_real d_sat = fmin(p[P_dmax], fmax(0.0, d));
    (void)u;
    if (d != d_sat && p[P_Ki] != 0.0)                         /* anti-windup: refaz a integral pelo duty saturado */
        integral = (p[P_Vdc] * (d_sat - d_ff) - p[P_Kp] * erro) / p[P_Ki];
    e->integral = integral;
    pwm_pulsos(&e->pwm, t, d_sat * p[P_TBPRD], U_g, -1);     /* CMPA = d·TBPRD: o pulso do intervalo vai à atuação g */
    maisim_scope("d", d_sat);
    maisim_scope("i_ref", p[P_i_ref]);
    maisim_scope("erro", erro);
}

arquivos.pwm.h:
/* pwm — biblioteca do MaiSim: o PWM digital. As mesmas contas, na mesma ordem, do pwm.py. Dois jeitos:

   1. O ePWM de um DSP: o contador a f_clk, com os registradores nos parâmetros do painel (nomes do C2000: f_clk, TBPRD,
      CTRMODE, SHDWAMODE, INTSEL, DB, TBPHS; veja o pwm.py). Com f_clk e TBPRD no painel, o MaiSim tira o Ts deles.
      Uso, no controle.c:
        #include "pwm.h"
        no struct Estado: PwmRegistradores pwm;
        no maisim_iniciar: pwm_iniciar_registradores(&e->pwm, p);
        no maisim_passo:   pwm_pulsos(&e->pwm, t, CMPA, U_g, -1);   (CMPA em contagens; o 2º índice: a complementar com o
                           tempo morto, ou -1) — o pulso do intervalo inteiro vai às atuações pelo maisim_padrao.
      O CMPA escrito agora só vale no evento de carga seguinte (o registrador sombra). Use a Atuação "Logo".
      No alvo, quem gera o pulso é o ePWM: troque o pwm_pulsos pela escrita do CMPA no registrador.

   2. O PWM comparado a cada Ts (o de antes; a resolução do PWM é o Ts):
        no struct Estado: PwmEstado pwm;
        no maisim_iniciar: pwm_iniciar(&e->pwm, p[P_fsw], PWM_SERRA);   (ou PWM_TRIANGULAR)
        no maisim_passo:   u[U_g] = pwm_passo(&e->pwm, t, d);   (1.0 ou 0.0; e->pwm.portadora vai ao scope) */
#ifndef PWM_H
#define PWM_H

#include "maisim_controle.h"

#define PWM_SERRA 0
#define PWM_TRIANGULAR 1
#define PWM_SOMBRA 8

typedef struct {
    maisim_real fsw;
    int tipo;
    maisim_real portadora;
} PwmEstado;

typedef struct {
    maisim_real tbprd, periodo, cps, dt, fase, db, cmpa, borda, contador;
    int modo, shdw, n, bruto, n_sombra;
    maisim_real sombra_ev[PWM_SOMBRA], sombra_cmpa[PWM_SOMBRA];
} PwmRegistradores;

void pwm_iniciar(PwmEstado *e, maisim_real fsw, int portadora);
maisim_real pwm_passo(PwmEstado *e, maisim_real t, maisim_real d);

void pwm_iniciar_registradores(PwmRegistradores *e, const maisim_real p[MAISIM_N_P]);
void pwm_pulsos(PwmRegistradores *e, maisim_real t, maisim_real CMPA, int u_a, int u_b);

#endif

